const normalizeName=value=>String(value??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toUpperCase().trim();
function flag(code,label){if(!code)return "";const countryCode=code.toLowerCase();return '<img class="country-flag" src="https://flagcdn.com/w40/'+countryCode+'.png" srcset="https://flagcdn.com/w80/'+countryCode+'.png 2x" alt="Bandera de '+esc(label)+'" title="'+esc(label)+'" loading="lazy">';}
function countryName(code){try{return new Intl.DisplayNames(["es"],{type:"region"}).of(code)||code;}catch{return code;}}
function pilotFlag(name){const entry=Object.entries(pilotCountries).find(([pilot])=>normalizeName(pilot)===normalizeName(name));const code=entry?.[1];return flag(code,code?countryName(code):"");}
function teamFlag(name,country){const countryCode=countryLabels[normalizeName(country)];const entry=Object.entries(teamCountries).find(([team])=>normalizeName(team)===normalizeName(name));const code=countryCode||entry?.[1];return flag(code,code?countryName(code):"");}
function circuitFlag(location){const normalized=normalizeName(location);const entry=Object.entries(circuitCountries).find(([place])=>normalized.includes(normalizeName(place)));const code=entry?.[1];return flag(code,code?countryName(code):"");}
const monthNumbers={ene:0,enero:0,feb:1,febrero:1,mar:2,marzo:2,abr:3,abril:3,may:4,mayo:4,jun:5,junio:5,jul:6,julio:6,ago:7,agosto:7,sep:8,septiembre:8,oct:9,octubre:9,nov:10,noviembre:10,dic:11,diciembre:11};
function eventDates(raw){const value=String(raw||"").toLowerCase().replace(/\./g,"");let match=value.match(/(\d{1,2})\s*([a-záéíóúñ]+)\s*[–-]\s*(\d{1,2})\s*([a-záéíóúñ]+)\s*(\d{4})/i);let sd,sm,ed,em,year;if(match){sd=+match[1];sm=monthNumbers[match[2]];ed=+match[3];em=monthNumbers[match[4]];year=+match[5];}else{match=value.match(/(\d{1,2})\s*[–-]\s*(\d{1,2})\s*([a-záéíóúñ]+)\s*(\d{4})/i);if(match){sd=+match[1];ed=+match[2];sm=em=monthNumbers[match[3]];year=+match[4];}else{match=value.match(/(\d{1,2})\s*([a-záéíóúñ]+)\s*(\d{4})/i);if(!match)return null;sd=ed=+match[1];sm=em=monthNumbers[match[2]];year=+match[3];}}if(sm==null||em==null)return null;return {start:new Date(year,sm,sd),end:new Date(year,em,ed)};}
function agendaEvents(){const events=[];for(const series of selectedAgendaSeries){const rows=siteData.calendars?.[series]||motorcycleCalendars[series]?.map(([round,event,location,date])=>({round,event,location,date}))||[];for(const item of rows){const dates=eventDates(item.date);if(!dates)continue;events.push({...item,...dates,series});}}const today=new Date();today.setHours(0,0,0,0);return events.filter(item=>item.end>=today).sort((a,b)=>a.start-b.start);}
function renderAgendaControls(){const host=$("#agendaSeries");if(!host)return;host.innerHTML=agendaSeriesList.map(series=>'<label class="agenda-chip"><input type="checkbox" value="'+series+'" '+(selectedAgendaSeries.includes(series)?"checked":"")+'><span>'+series+'</span></label>').join("");host.querySelectorAll("input").forEach(input=>input.addEventListener("change",()=>{selectedAgendaSeries=[...host.querySelectorAll("input:checked")].map(item=>item.value);try{localStorage.setItem("mc-agenda-series",JSON.stringify(selectedAgendaSeries))}catch(_){}$("#accountPreferenceSeries").querySelectorAll("input").forEach(item=>{item.checked=selectedAgendaSeries.includes(item.value)});renderAgenda();if(accountState.user)saveAccountPreferences(false);}));}
function renderAgenda(){const grid=$("#agendaGrid");if(!grid)return;const events=agendaEvents();const lang=document.documentElement.lang==="en"?"en":"es";const locale=lang==="es"?"es-ES":"en-GB";$("#agendaStatus").textContent=lang==="es"?(selectedAgendaSeries.length?selectedAgendaSeries.length+" categorías seleccionadas":"Selecciona una categoría"):(selectedAgendaSeries.length?selectedAgendaSeries.length+" series selected":"Select a series");if(!selectedAgendaSeries.length){grid.innerHTML='<article class="agenda-card agenda-empty"><h3>'+(lang==="es"?"Elige tus campeonatos":"Choose your championships")+'</h3><p>'+(lang==="es"?"Selecciona una o varias categorías para ver sus próximos fines de semana.":"Select one or more series to see their upcoming race weekends.")+'</p></article>';$("#agendaExport").disabled=true;return;}if(!events.length){grid.innerHTML='<article class="agenda-card agenda-empty"><h3>'+(lang==="es"?"No quedan pruebas en el calendario cargado":"No upcoming events in the loaded calendar")+'</h3><p>'+(lang==="es"?"Consulta las fuentes oficiales para los cambios y el calendario de la próxima temporada.":"Check official sources for changes and next season’s calendar.")+'</p></article>';$("#agendaExport").disabled=true;return;}$("#agendaExport").disabled=false;const today=new Date();today.setHours(0,0,0,0);const nextBySeries=new Map();events.forEach(item=>{if(!nextBySeries.has(item.series))nextBySeries.set(item.series,item);});const cards=[...nextBySeries.values()].sort((a,b)=>a.start-b.start);grid.innerHTML=cards.map(item=>{const day=Math.ceil((item.start-today)/86400000);const ongoing=item.start<=today&&item.end>=today;const countdown=ongoing?(lang==="es"?"Fin de semana en curso":"Race weekend is underway"):(day===0?(lang==="es"?"Empieza hoy":"Starts today"):(lang==="es"?"Empieza en "+day+" días":"Starts in "+day+" days"));const standings=siteData.standings?.[item.series]?.drivers||[];const leader=standings.find(row=>Number(row.position)===1)||standings[0];const second=standings.find(row=>Number(row.position)===2);const gap=leader&&second?Math.max(0,Number(leader.points)-Number(second.points)):null;const source=siteData.sources?.[item.series]||officialLinks[item.series];const eventName=item.event||item.name||item.series;const scheduleLink=["F1","F2","F3","WEC"].includes(item.series)?"race-schedule.html?series="+encodeURIComponent(item.series)+"&round="+encodeURIComponent(item.round??1):officialLinks[item.series];return '<article class="agenda-card"><div class="agenda-card-top"><span>'+esc(item.series)+'</span><span>'+esc(item.date)+'</span></div><h3>'+esc(eventName)+'</h3><p class="agenda-location">'+esc(item.location||"")+'</p><strong class="agenda-countdown">'+esc(countdown)+'</strong>'+(leader?'<p class="agenda-context">'+(lang==="es"?"Líder actual":"Current leader")+': <b>'+esc(leader.name)+'</b>'+(gap!==null?' · '+(lang==="es"?"ventaja de":"leads by")+' '+esc(gap)+' '+(lang==="es"?"pts":"pts"):'')+'</p>':'')+'<p class="agenda-time-note">'+(lang==="es"?"La hora de la primera sesión se confirma en el programa oficial.":"Check the official timetable for the first session time.")+'</p><a class="card-link" href="'+esc(scheduleLink)+'" '+(["F1","F2","F3","WEC"].includes(item.series)?"":"target=\"_blank\" rel=\"noopener\"")+'>'+(lang==="es"?"Ver horarios oficiales":"Official timetable")+' ↗</a></article>';}).join("");}
function exportAgenda(){const events=agendaEvents();if(!events.length)return;const stamp=date=>date.getFullYear()+String(date.getMonth()+1).padStart(2,"0")+String(date.getDate()).padStart(2,"0");const escapeICS=value=>String(value||"").replace(/\\/g,"\\\\").replace(/\n/g,"\\n").replace(/,/g,"\\,").replace(/;/g,"\\;");const lines=["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//Motor Competicion//Mi agenda//ES","CALSCALE:GREGORIAN","METHOD:PUBLISH"];events.forEach(item=>{const end=new Date(item.end);end.setDate(end.getDate()+1);const uid=encodeURIComponent(item.series+"-"+item.event+"-"+stamp(item.start))+"@motorcompeticion";lines.push("BEGIN:VEVENT","UID:"+uid,"DTSTAMP:"+new Date().toISOString().replace(/[-:]/g,"").replace(/\.\d{3}/,""),"DTSTART;VALUE=DATE:"+stamp(item.start),"DTEND;VALUE=DATE:"+stamp(end),"SUMMARY:"+escapeICS(item.series+" · "+(item.event||item.name||"Carrera")),"LOCATION:"+escapeICS(item.location),"DESCRIPTION:"+escapeICS("Fin de semana de carrera. Confirma los horarios de las sesiones en "+(siteData.sources?.[item.series]||officialLinks[item.series])),"END:VEVENT");});lines.push("END:VCALENDAR");const blob=new Blob([lines.join("\r\n")],{type:"text/calendar;charset=utf-8"});const link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download="mi-agenda-motor-competicion.ics";link.click();URL.revokeObjectURL(link.href);}
function renderNews(){
  const grid=$("#newsGrid");
  let items=(siteData.news||[]).filter(n=>currentNewsSeries==="Todos"||n.series===currentNewsSeries);
  const spoilerSeries=new Set();
  if(accountState.user?.preferences?.hideSpoilers){const today=new Date();today.setHours(0,0,0,0);for(const series of agendaSeriesList){const rows=siteData.calendars?.[series]||motorcycleCalendars[series]?.map(([round,event,location,date])=>({round,event,location,date}))||[];if(rows.some(row=>{const dates=eventDates(row.date);return dates&&dates.start<=today&&dates.end>=today;}))spoilerSeries.add(series);}items=items.filter(news=>!spoilerSeries.has(news.series));}
  const interfaceLanguage=document.documentElement.lang==="en"?"en":"es";
  const displayLanguage=currentNewsLanguage==="all"?interfaceLanguage:currentNewsLanguage;
  grid.innerHTML="";
  const newsCheck=siteData.newsCheckedAt||siteData.newsUpdatedAt;
  const newsStamp=newsCheck?" · sincronizado "+new Date(newsCheck).toLocaleString(displayLanguage==="es"?"es-ES":"en-GB"):"";
  const statusLabel=currentNewsLanguage==="all"?(interfaceLanguage==="es"?"Todas las noticias":"All news"):(displayLanguage==="es"?"Noticias en castellano":"News in English");
  $("#newsStatus").textContent=items.length?statusLabel+newsStamp:(displayLanguage==="es"?"No hay noticias para este filtro.":"No news for this filter.")+newsStamp;
  if(!items.length){const hidden=spoilerSeries.size>0;grid.innerHTML='<article class="news-card"><h3>'+(hidden?(displayLanguage==="es"?"Resultados ocultos hasta terminar la prueba":"Results hidden until the event ends"):(displayLanguage==="es"?"Sin noticias disponibles":"No news available"))+'</h3></article>';return;}
  items.forEach(n=>{
    const originalLanguage=n.language||"en";
    const localizedLanguage=currentNewsLanguage==="all"?originalLanguage:displayLanguage;
    const localized=n.translations?.[localizedLanguage]||(localizedLanguage===originalLanguage?{title:n.title,summary:n.summary}:n.translations?.[originalLanguage]||{title:n.title,summary:n.summary});
    const card=document.createElement("article");
    card.className="news-card";
    card.innerHTML='<div class="card-top"><span>'+esc(n.series)+' · '+esc(n.source)+'</span><span>'+esc(n.date)+'</span></div><h3>'+esc(localized.title||n.title)+'</h3><p>'+esc(localized.summary||n.summary||"")+'</p><a class="card-link" href="'+esc(n.url)+'" target="_blank" rel="noopener">'+(interfaceLanguage==="es"?"Leer en la fuente":"Read source")+' <span>↗</span></a>';
    grid.append(card);
  });
}
function renderCalendar(){const now=new Date();const months={ene:0,feb:1,mar:2,abr:3,may:4,jun:5,jul:6,ago:7,sep:8,oct:9,nov:10,dic:11};const sourceRows=siteData.calendars?.[currentCalendarSeries]||motorcycleCalendars[currentCalendarSeries]?.map(([round,event,location,date])=>({round,event,location,date}))||[];const rows=sourceRows.map(e=>{const raw=String(e.date);let endDate=null;let m=raw.match(/(\d{1,2})\s*(ene|feb|mar|abr|may|jun|jul|ago|sep|oct|nov|dic)\s*[–-]\s*(\d{1,2})\s*(ene|feb|mar|abr|may|jun|jul|ago|sep|oct|nov|dic)\s*(\d{4})/i);if(m){endDate=new Date(Number(m[5]),months[m[4].toLowerCase()],Number(m[3]),23,59,59);}else{m=raw.match(/(\d{1,2})\s*[–-]\s*(\d{1,2})\s*(ene|feb|mar|abr|may|jun|jul|ago|sep|oct|nov|dic)\s*(\d{4})/i);if(m){endDate=new Date(Number(m[4]),months[m[3].toLowerCase()],Number(m[2]),23,59,59);}else{m=raw.match(/(\d{1,2})\s*(ene|feb|mar|abr|may|jun|jul|ago|sep|oct|nov|dic)\s*(\d{4})/i);if(m)endDate=new Date(Number(m[3]),months[m[2].toLowerCase()],Number(m[1]),23,59,59);}}const status=endDate&&endDate<now?"past":"upcoming";return {...e,status};}).filter(e=>{const s=$("#calendarStatus").value;return s==="all"||e.status===s;});const motoSeries=["MotoGP","Moto2","Moto3","Superbikes"].includes(currentCalendarSeries);$("#calendarBody").innerHTML=rows.length?rows.map((e,i)=>'<tr><td>'+String(e.round??i+1).padStart(2,"0")+'</td><td><strong>'+esc(e.event)+'</strong></td><td>'+circuitFlag(e.location)+(motoSeries?'<a class="circuit-link" href="'+esc(officialLinks[currentCalendarSeries])+'" target="_blank" rel="noopener">'+esc(e.location)+' ↗</a>':'<a class="circuit-link" href="race-schedule.html?series='+encodeURIComponent(currentCalendarSeries)+'&amp;round='+encodeURIComponent(e.round??i+1)+'">'+esc(e.location)+'</a>')+'</td><td>'+esc(e.date)+'</td><td><span class="status-pill '+(e.status==="past"?"past":"")+'">'+(e.status==="past"?"Celebrado":"Próximo")+'</span></td></tr>').join(""):'<tr><td colspan="5">No hay rondas publicadas para este campeonato.</td></tr>';const lang=document.documentElement.lang==="en"?"en":"es";const checked=siteData.calendarsCheckedAt?.[currentCalendarSeries];const source=siteData.sources?.[currentCalendarSeries]||officialLinks[currentCalendarSeries];$("#calendarDisclaimer").innerHTML=(lang==="es"?"Calendario 2026 · ":"2026 calendar · ")+(checked?(lang==="es"?"última consulta ":"last checked ")+esc(new Date(checked).toLocaleString(lang==="es"?"es-ES":"en-GB")):(lang==="es"?"fecha de verificación no registrada":"verification date not recorded"))+" · "+(lang==="es"?"Fuente: ":"Source: ")+'<a href="'+esc(source)+'" target="_blank" rel="noopener">'+esc(currentCalendarSeries)+" ↗</a>";}
function renderStandings(){const all=siteData.standings||{};const data=all[currentStandingsSeries]||{};let rows=data[currentStandingsType]||[];if(currentStandingsSeries==="WEC"){$("#wecClassWrap").hidden=false;const cat=$("#wecClass").value;rows=data[cat]?.[currentStandingsType]||[];}else $("#wecClassWrap").hidden=true;$("#standingsBody").innerHTML=rows.length?rows.map((r,i)=>'<tr><td>'+esc(r.position??i+1)+'</td><td><strong>'+(currentStandingsType==="drivers"?pilotFlag(r.name):teamFlag(r.name,r.team))+esc(r.name)+'</strong></td><td>'+esc(r.team||"—")+'</td><td>'+esc(r.points??"—")+'</td></tr>').join(""):'<tr><td colspan="4">Todavía no hay una tabla verificada para esta categoría. Consulta la clasificación oficial en el enlace inferior.</td></tr>';const lang=document.documentElement.lang==="en"?"en":"es";const updated=siteData.standingsUpdatedAt?.[currentStandingsSeries];$("#standingsUpdated").textContent=updated?(lang==="es"?"Actualizada: ":"Updated: ")+new Date(updated).toLocaleString(lang==="es"?"es-ES":"en-GB"):(lang==="es"?"Fecha de actualización no registrada":"Update date not recorded");const source=currentStandingsType==="teams"?(officialTeamStandingsLinks[currentStandingsSeries]||siteData.standingsSources?.[currentStandingsSeries]||officialLinks[currentStandingsSeries]):(siteData.standingsSources?.[currentStandingsSeries]||officialStandingsLinks[currentStandingsSeries]||officialLinks[currentStandingsSeries]);$("#standingsDisclaimer").innerHTML=(lang==="es"?(rows.length?'Fuente de datos de esta tabla: ':'Sin tabla local verificada. Fuente oficial: '):(rows.length?'Data source for this table: ':'No verified local table. Official source: '))+'<a href="'+esc(source)+'" target="_blank" rel="noopener">'+esc(currentStandingsSeries)+' ↗</a>.';}
function renderLineup(){const data=nextSeasonLineups[currentLineupSeries]||{seatLabels:["Piloto 1","Piloto 2"],teams:[]};const rows=data.teams;const known=rows.reduce((sum,row)=>sum+row.drivers.length,0);$("#lineupStatus").textContent=(known?known+" piloto"+(known===1?" confirmado":"s confirmados")+" en "+rows.length+" equipo"+(rows.length===1?"":"s")+" · temporada 2027":"Aún no hay pilotos confirmados para 2027 en esta categoría.")+(data.note?" · "+data.note:"");$("#lineupGrid").innerHTML=rows.length?'<div class="lineup-table-wrap"><table class="lineup-table"><thead><tr><th>Equipo</th>'+data.seatLabels.map(label=>'<th>'+esc(label)+'</th>').join("")+'<th>Situación</th></tr></thead><tbody>'+rows.map(row=>'<tr><th scope="row">'+esc(row.team)+'</th>'+data.seatLabels.map((label,index)=>'<td>'+(row.drivers[index]?pilotFlag(row.drivers[index])+esc(row.drivers[index]):'<span class="lineup-pending">Por confirmar</span>')+'</td>').join("")+'<td><span class="lineup-situation '+(row.drivers.length===data.seatLabels.length?'complete':'pending')+'">'+(row.drivers.length===data.seatLabels.length?(data.note?'Pilotos confirmados':'Alineación confirmada'):(data.seatLabels.length-row.drivers.length===1?'Un asiento pendiente':(data.seatLabels.length-row.drivers.length)+' asientos pendientes'))+'</span> · <a href="'+esc(row.url)+'" target="_blank" rel="noopener">Fuente ↗</a></td></tr>').join("")+'</tbody></table></div>':'<article class="lineup-card lineup-empty"><h3>Sin anuncios confirmados todavía</h3><p>Cuando los equipos publiquen sus pilotos para 2027, aparecerán aquí con su fuente oficial.</p><a class="card-link" href="'+esc(officialLinks[currentLineupSeries])+'" target="_blank" rel="noopener">Web oficial de '+esc(currentLineupSeries)+' ↗</a></article>';}
async function loadData(){try{let res=await fetch(API_URL+"?action=all&v="+Date.now(),{cache:"no-store"});if(!res.ok||!(res.headers.get("content-type")||"").includes("application/json"))throw new Error("API no activa");siteData=await res.json();}catch(_){try{const res=await fetch(DATA_URL+"?v="+Date.now(),{cache:"no-store"});if(!res.ok)throw new Error("No se pudo leer el JSON");siteData=await res.json();}catch(e){$("#newsStatus").textContent="No se pudieron cargar los datos";}}renderNews();renderCalendar();renderStandings();renderLineup();renderAgenda();}
function accountMessage(message,isError=false){const status=$("#accountStatus");status.textContent=message;status.classList.toggle("error",isError);}
function accountTeamOptions(seriesList){const options=[];const add=(series,name)=>{if(name&&String(name).trim()&&!options.some(option=>option.value===series+"::"+name))options.push({series,value:series+"::"+name,label:String(name)});};for(const series of seriesList){const data=siteData.standings?.[series]||{};const groups=series==="WEC"?[data.Hypercar,data.LMGT3]:[data];for(const group of groups)for(const row of group?.teams||[])add(series,row.name||row.team);for(const row of nextSeasonLineups[series]?.teams||[])add(series,row.team);}return options.sort((a,b)=>a.series.localeCompare(b.series)||a.label.localeCompare(b.label));}
async function accountRequest(op,body){let csrf=accountState.csrf;if(op!=="csrf"&&op!=="me"&&!csrf){const token=await accountRequest("csrf");csrf=token.csrf;}const options=body===undefined?{credentials:"same-origin",cache:"no-store"}:{method:"POST",credentials:"same-origin",cache:"no-store",headers:{"Content-Type":"application/json","X-CSRF-Token":csrf},body:JSON.stringify(body)};const response=await fetch(API_URL+"?action=auth&op="+encodeURIComponent(op),options);let result;try{result=await response.json()}catch(_){throw new Error("El servidor de cuentas no está disponible. GitHub Pages no ejecuta PHP; se necesita alojar api.php en un servidor PHP.");}if(!response.ok||!result.ok)throw new Error(result.error||"No se pudo completar la operación.");if(result.csrf)accountState.csrf=result.csrf;return result;}
function renderAccount(){const logged=!!accountState.user;$("#accountForm").hidden=logged;$("#accountPreferences").hidden=!logged;$("#accountOpen").textContent=logged?"Mi cuenta":"Iniciar sesión";$("#accountWelcome").textContent=logged?"Sesión iniciada como "+accountState.user.email:"";if(!logged)return;const p=accountState.user.preferences||{};selectedAgendaSeries=Array.isArray(p.series)?p.series:["F1","MotoGP","WEC"];try{localStorage.setItem("mc-agenda-series",JSON.stringify(selectedAgendaSeries))}catch(_){}const drawSeries=series=>$("#accountPreferenceSeries").innerHTML=agendaSeriesList.map(name=>'<label class="check-chip"><input type="checkbox" value="'+name+'" '+(series.includes(name)?"checked":"")+'><span>'+name+'</span></label>').join("");const drawTeams=(series,selected)=>{$("#accountPreferenceTeams").innerHTML=accountTeamOptions(series).map(option=>'<label class="check-chip"><input type="checkbox" value="'+esc(option.value)+'" '+(selected.includes(option.value)?"checked":"")+'><span>'+esc(option.series+" · "+option.label)+'</span></label>').join("")||'<span class="fine-print">Elige categorías para cargar equipos.</span>'};const selectedTeams=Array.isArray(p.teams)?p.teams:[];drawSeries(selectedAgendaSeries);drawTeams(selectedAgendaSeries,selectedTeams);$("#accountPreferenceSeries").querySelectorAll("input").forEach(input=>input.addEventListener("change",()=>drawTeams([...$("#accountPreferenceSeries").querySelectorAll("input:checked")].map(item=>item.value),[...$("#accountPreferenceTeams").querySelectorAll("input:checked")].map(item=>item.value))));$("#alertRaceWeekend").checked=!!p.raceWeekend;$("#alertNews").checked=!!p.news;$("#hideSpoilers").checked=!!p.hideSpoilers;$("#alertLead").value=String([15,30,60].includes(Number(p.leadMinutes))?p.leadMinutes:30);renderAgendaControls();renderAgenda();}
async function initAccount(){try{const token=await accountRequest("csrf");accountState.csrf=token.csrf;const result=await accountRequest("me");accountState.user=result.user;if(accountState.user)renderAccount();}catch(error){accountMessage(error.message,true);}}
async function saveAccountPreferences(showMessage=true){if(!accountState.user)return;const selected=[...$("#accountPreferenceSeries").querySelectorAll("input:checked")].map(input=>input.value);const preferences={series:selected,teams:[...$("#accountPreferenceTeams").querySelectorAll("input:checked")].map(input=>input.value).filter(value=>selected.includes(value.split("::")[0])),raceWeekend:$("#alertRaceWeekend").checked,news:$("#alertNews").checked,hideSpoilers:$("#hideSpoilers").checked,leadMinutes:Number($("#alertLead").value)};try{const result=await accountRequest("save_preferences",{preferences});accountState.user=result.user;selectedAgendaSeries=selected;renderAccount();if((preferences.raceWeekend||preferences.news)&&"Notification" in window&&Notification.permission==="default")await Notification.requestPermission();if(showMessage)accountMessage("Preferencias guardadas en tu cuenta. Los avisos del navegador funcionan mientras la app está abierta.");}catch(error){accountMessage(error.message,true);}}
function browserNotice(title,body,tag){if(!accountState.user||!("Notification" in window)||Notification.permission!=="granted")return;const show=()=>new Notification(title,{body,tag,icon:"./icons/icon-192.svg"});if("serviceWorker" in navigator)navigator.serviceWorker.ready.then(reg=>reg.showNotification(title,{body,tag,icon:"./icons/icon-192.svg"})).catch(show);else show();}
function checkRaceWeekendReminder(){if(!accountState.user?.preferences?.raceWeekend)return;const now=Date.now(),lead=Number(accountState.user.preferences.leadMinutes||30)*60000;const event=agendaEvents().find(item=>item.start.getTime()>now);if(!event)return;const target=event.start.getTime()-lead,key="mc-race-reminder:"+event.series+":"+event.start.toISOString();let sent=false;try{sent=localStorage.getItem(key)==="1"}catch(_){}if(!sent&&now>=target&&now<event.start.getTime()){browserNotice("Fin de semana de "+event.series,"Se acerca "+(event.event||event.name)+" · "+event.date+". Confirma la hora de la primera sesión en el programa oficial.",key);try{localStorage.setItem(key,"1")}catch(_){}}}
async function checkNewsReminder(){if(!accountState.user?.preferences?.news||!accountState.user.preferences.series?.length)return;try{const response=await fetch(DATA_URL+"?v="+Date.now(),{cache:"no-store"});if(!response.ok)return;const fresh=await response.json();const current=String(fresh.newsUpdatedAt||"");if(!current||!window.lastNewsAlertCheck){window.lastNewsAlertCheck=current;return;}if(current!==window.lastNewsAlertCheck){window.lastNewsAlertCheck=current;const allowed=new Set(accountState.user.preferences.series);const teamPicks=accountState.user.preferences.teams||[];const item=(fresh.news||[]).find(news=>{if(!allowed.has(news.series))return false;if(!teamPicks.length)return true;const terms=teamPicks.filter(value=>value.startsWith(news.series+"::")).map(value=>value.split("::")[1].toLowerCase());if(!terms.length)return false;const text=(news.title+" "+(news.summary||"")).toLowerCase();return terms.some(team=>text.includes(team));});if(item)browserNotice("Noticias actualizadas · "+item.series,item.translations?.[document.documentElement.lang]?.title||item.title,"mc-news:"+current);}}catch(_){}}
